# Incremental update of the verified f4985b1 UX release only.
import base64, zlib, hashlib, json, zipfile
from pathlib import Path
PAYLOAD = """

"""
changes = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
prepared = []
for item in changes:
    path = Path(item['path'])
    old = path.read_text(encoding='utf-8') if path.exists() else None
    actual = hashlib.sha256(old.encode()).hexdigest() if old is not None else None
    if actual != item['before']:
        raise RuntimeError('The UX baseline changed; refusing to replace ' + str(path))
    text = item.get('text', old)
    for before, after in item.get('edits', []):
        if text.count(before) != 1:
            raise RuntimeError('Ambiguous edit in ' + str(path))
        text = text.replace(before, after, 1)
    if hashlib.sha256(text.encode()).hexdigest() != item['after']:
        raise RuntimeError('Source checksum mismatch: ' + str(path))
    prepared.append((path, text))
for path, text in prepared:
    crlf = path.exists() and b'\r\n' in path.read_bytes()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding='utf-8', newline='\r\n' if crlf else '\n')
Path('release').mkdir(exist_ok=True)
with zipfile.ZipFile('release/review-source.zip','w',zipfile.ZIP_DEFLATED) as z:
    for directory in ['src','tests','docs','.github','scripts']:
        for p in Path(directory).rglob('*'):
            if p.is_file() and not any(v in p.parts for v in ['bin','obj','__pycache__','ux-patches']): z.write(p,p.as_posix())
    for name in ['Directory.Build.props','Directory.Packages.props','MyLovePixel.slnx','global.json','HANDOFF.md','README.md','THIRD_PARTY_NOTICES.md']:
        if Path(name).is_file(): z.write(name)
print('Installed verified named-palette changes:', len(prepared), 'files; all other UX source preserved.')
